import{_ as t,o,c as n,a2 as a}from"./chunks/framework.C-si7TFR.js";const m=JSON.parse('{"title":"WeCom agent remote control","description":"","frontmatter":{"title":"WeCom agent remote control"},"headers":[],"relativePath":"guide/remote-control.md","filePath":"guide/remote-control.md"}'),r={name:"guide/remote-control.md"};function i(s,e,l,c,d,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="wecom-agent-remote-control" tabindex="-1">WeCom agent remote control <a class="header-anchor" href="#wecom-agent-remote-control" aria-label="Permalink to &quot;WeCom agent remote control&quot;">​</a></h1><p>A WeCom remote channel allows approved users to converse with a selected agent over a long-lived connection. It is neither a legacy robot trigger nor a message-sending node.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>An available agent and model configuration.</li><li>A supported Bot ID and long-connection Secret from the WeCom administration console.</li><li>Network access for the required connection; the channel status determines connectivity.</li><li>An understanding of the agent&#39;s tools, working directory and accessible data.</li></ul><h2 id="add-a-channel" tabindex="-1">Add a channel <a class="header-anchor" href="#add-a-channel" aria-label="Permalink to &quot;Add a channel&quot;">​</a></h2><ol><li>Open remote channels from an agent card or the workspace entry.</li><li>Select <strong>Add remote</strong>, choose an agent and name the channel.</li><li>Enter the Bot ID and Secret. Never place real values in documentation, screenshots or public configuration.</li><li>Configure the user allowlist. Consider <code>*</code> only when you understand the exposure.</li><li>Select <strong>Connect and save</strong>, confirm the channel is usable, then send a no-side-effect message from an allowed account.</li></ol><p>Enable or disable the channel to control remote access. Web access to its conversations does not grant the remote user web administration permissions.</p><h2 id="distinct-capabilities" tabindex="-1">Distinct capabilities <a class="header-anchor" href="#distinct-capabilities" aria-label="Permalink to &quot;Distinct capabilities&quot;">​</a></h2><ul><li><strong>WeCom remote control:</strong> accepts user instructions, drives an agent and returns conversation results.</li><li><strong>Legacy WeCom robot trigger:</strong> an old workflow entry whose new-creation entry is hidden.</li><li><strong>Send WeCom message node:</strong> sends a message from a workflow; it does not establish agent remote control.</li></ul><h2 id="security-and-troubleshooting" tabindex="-1">Security and troubleshooting <a class="header-anchor" href="#security-and-troubleshooting" aria-label="Permalink to &quot;Security and troubleshooting&quot;">​</a></h2><p>An allowlist does not replace least-privilege tool authorization. On failure, disable the channel and inspect Bot settings, the allowlist, network and channel errors before examining agent sessions and tool results. Rotate an exposed Secret at its provider; deleting a screenshot is not sufficient.</p>',11)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
